/// <reference types="@stdlib/types"/>

/**
* Interface for Spearman test result.
*/
interface Results {
	/**
	* Used significance level.
	*/
	alpha: number;

	/**
	* Test decision.
	*/
	rejected: boolean;

	/**
	* p-value of the test.
	*/
	pValue: number;

	/**
	* Value of the test statistic.
	*/
	statistic: number;

	/**
	* Confidence interval for the correlation coefficient.
	*/
	ci: Array<number>;

	/**
	* Alternative hypothesis (`two-sided`, `less` or `greater`).
	*/
	alternative: string;

	/**
	* Name of the test.
	*/
	method: string;

	/**
	* Assumed correlation coefficient under H0.
	*/
	nullValue: number;

	/**
	* Spearman rank correlation coefficient.
	*/
	scorr: number;

	/**
	* Prints the formatted test output.
	*/
	print: Function;
}

/**
* Interface for Spearman test options.
*/
interface Options {
	/**
	* Significance level. Default: `0.05`.
	*/
	alpha?: number;

	/**
	* Alternative hypothesis. Default: `'two-sided'`.
	*/
	alternative?: 'two-sided' | 'less' | 'greater';

	/**
	* Correlation coefficient under H0. Default: `0.0`.
	*/
	rho?: number;
}

/**
* Computes a Spearman rank correlation test between paired samples.
*
* @param x - first data array
* @param y - second data array
* @param options - function options
* @returns test result object
*
* @example
* var x = [ 1, 2, 3, 4, 5 ];
* var y = [ 2, 4, 5, 4, 6 ];
* var out = spearmanTest( x, y );
*/
declare function spearmanTest( x: Array<number>, y: Array<number>, options?: Options ): Results;


// EXPORTS //

export = spearmanTest;
